package graph

// This file is NOT regenerated by gqlgen. Helpers used by user.resolvers.go
// live here so `gqlgen generate` doesn't shuffle them into a warning block.

import (
	"context"

	"storeapi/internal/models"
)

func (r *userResolver) loadAddresses(ctx context.Context, userID string) ([]*models.Address, error) {
	l := loaders(ctx)

	addressIDs, err := l.AddressIDsByUser.Load(ctx, userID)
	if err != nil {
		return nil, err
	}
	addresses, err := l.Address.LoadAll(ctx, addressIDs)
	if err != nil {
		return nil, err
	}

	out := make([]*models.Address, 0, len(addresses))
	for _, a := range addresses {
		if a != nil {
			out = append(out, a)
		}
	}
	return out, nil
}
